function validate(input) {
  const [{ Teams = [], Passes = [] }] = input;
  const team = new Map(), names = new Map();
  for (const [id, name] of Teams) {
    if (id === null || name === null) return 'Every player needs a player_id and a team_name.';
    if (team.has(id)) return `player_id ${id} appears twice in Teams.`;
    team.set(id, name);
    const key = name.toLowerCase();
    if (names.has(key) && names.get(key) !== name) return `Team ${name} is spelled two ways.`;
    names.set(key, name);
  }
  if (names.size > 2) return 'A match has at most two teams.';
  const times = new Set();
  for (const [from, time, to] of Passes) {
    if (!team.has(from) || !team.has(to)) return 'Every pass must be between players listed in Teams.';
    if (from === to) return `Player ${from} passes to themselves.`;
    if (time === null || !/^\d\d:[0-5]\d$/.test(time) || time > '90:00') return `time_stamp ${time} must be MM:SS between 00:00 and 90:00.`;
    if (times.has(time)) return `Two passes happen at ${time}.`;
    times.add(time);
  }
  return null;
}

