function generate(rand, size) {
  const clubs = ['Arsenal', 'Chelsea', 'Ajax', 'Porto', 'Lazio', 'Benfica'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const home = pick(clubs);
  let away = pick(clubs);
  while (away === home) away = pick(clubs);
  const players = size === 'small' ? Math.floor(rand() * 9) : 30;
  const Teams = [];
  for (let i = 0; i < players; i++) Teams.push([i + 1, i === 0 ? home : i === 1 ? away : rand() < 0.5 ? home : away]);
  const count = players < 2 ? 0 : size === 'small' ? Math.floor(rand() * 10) : 2000;
  // Distinct match seconds, sorted, become the time stamps.
  const seconds = new Set();
  while (seconds.size < count) seconds.add(Math.floor(rand() * 5401));
  const times = [...seconds].sort((a, b) => a - b).map(s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`);
  // The ball usually moves on from whoever received it; sometimes another player starts a pass.
  const Passes = [];
  let holder = 1 + Math.floor(rand() * players);
  for (const at of times) {
    if (rand() < 0.25) holder = 1 + Math.floor(rand() * players);
    const own = Teams[holder - 1][1];
    const mates = Teams.filter(([id, name]) => id !== holder && name === own).map(([id]) => id);
    const others = Teams.filter(([, name]) => name !== own).map(([id]) => id);
    const pool = mates.length && (rand() < 0.75 || !others.length) ? mates : others.length ? others : mates;
    if (!pool.length) continue;
    const to = pick(pool);
    Passes.push([holder, at, to]);
    holder = to;
  }
  // Store the rows out of time order.
  for (let i = Passes.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Passes[i], Passes[j]] = [Passes[j], Passes[i]];
  }
  return [{ Teams, Passes }];
}
